import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public long nextLong() {
            int b = readByte();
            while (b != -1 && b <= ' ') {
                b = readByte();
            }
            if (b == -1) return -1;
            long val = 0;
            while (b >= '0' && b <= '9') {
                val = val * 10 + (b - '0');
                b = readByte();
            }
            return val;
        }

        public int nextInt() {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n < 4) {
            System.out.println("N");
            return;
        }

        long[] pos = new long[n];
        pos[0] = 0;
        for (int i = 0; i < n - 1; i++) {
            long l = scanner.nextLong();
            pos[i + 1] = pos[i] + l;
        }
        long lastL = scanner.nextLong();
        long totalLength = pos[n - 1] + lastL;

        if (totalLength % 2 != 0) {
            System.out.println("N");
            return;
        }

        long half = totalLength / 2;
        int count = 0;
        int j = 0;

        for (int i = 0; i < n; i++) {
            long target = pos[i] + half;
            if (target >= totalLength) {
                break;
            }
            while (j < n && pos[j] < target) {
                j++;
            }
            if (j < n && pos[j] == target) {
                count++;
                if (count >= 2) {
                    System.out.println("S");
                    return;
                }
            }
        }

        System.out.println("N");
    }
}
